WITH base AS (SELECT *, CONCAT(method, ', ', status) AS method_status, TO_DATE(paid_at) AS paid_at_date FROM payments WHERE paid_at >= TIMESTAMP '2023-05-13 09:00:00' AND order_id IS NOT NULL), with_gaps AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL '7' DAY THEN 1 ELSE 0 END AS session_start_flag FROM base), sessionized AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM with_gaps) SELECT status, DATE_TRUNC('MONTH', paid_at_date) AS activity_month, COUNT_IF(method = 'card') AS card_events, COUNT(*) FILTER (WHERE status = 'REFUNDED') AS refunded_rows, DENSE_RANK() OVER (PARTITION BY status ORDER BY COUNT_IF(method = 'card') DESC) AS card_events_dense_rank FROM sessionized GROUP BY status, activity_month
